  --panel: rgba(13, 19, 32, .78);
  --panel-2: rgba(18, 26, 43, .82);
  --accent: #ff4a2b;
  --accent-2: #ffb03a;
  --cyan: #35e6ff;
  --lime: #d6ff4b;
  --green: #45f0a2;
  --violet: #9c7bff;
  --car-color: #ff4a2b;
  --car-dark: #8f1208;
  --car-accent: #35e6ff;
  --radius: 18px;
  --font-display: "Arial Black", "Impact", "Franklin Gothic Heavy", "Haettenschweiler", sans-serif;
  --font-ui: "Inter", "Segoe UI", system-ui, -apple-system, sans-serif;
  --font-mono: "SFMono-Regular", "Roboto Mono", "Courier New", monospace;
  --shadow: 0 24px 70px rgba(0, 0, 0, .45);
  --safe-b: env(safe-area-inset-bottom, 0px);
  --safe-t: env(safe-area-inset-top, 0px);
}

* { box-sizing: border-box; margin: 0; padding: 0; }
html, body { height: 100%; }
html { background: var(--bg); }
body {
  font-family: var(--font-ui);
  color: var(--ink);
  background: var(--bg);
  overflow: hidden;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overscroll-behavior: none;
  -webkit-tap-highlight-color: transparent;
}
button { font: inherit; color: inherit; background: none; border: 0; cursor: pointer; }
svg { display: block; }
.svg-defs { position: absolute; width: 0; height: 0; overflow: hidden; }
.icon { width: 20px; height: 20px; flex: none; }

#app { position: relative; width: 100%; height: 100%; height: 100dvh; overflow: hidden; }

/* ── ambient backdrop ───────────────────────────────────────── */
.ambient { position: absolute; inset: 0; overflow: hidden; pointer-events: none; z-index: 0; background:
  radial-gradient(120% 90% at 50% 0%, #101a30 0%, #070b14 48%, #04060c 100%);
}
.ambient::before {
  content: ""; position: absolute; inset: 0;
  background:
    radial-gradient(55% 45% at 78% 18%, rgba(53, 230, 255, .10), transparent 65%),
    radial-gradient(50% 42% at 18% 28%, rgba(255, 74, 43, .12), transparent 68%);
}
.ambient-grid {
  position: absolute; left: -40%; right: -40%; bottom: -34%; height: 78%;
  background-image:
    linear-gradient(rgba(83, 220, 255, .34) 1px, transparent 1px),
    linear-gradient(90deg, rgba(83, 220, 255, .34) 1px, transparent 1px);
  background-size: 74px 74px;
  transform: perspective(480px) rotateX(64deg);
  transform-origin: 50% 100%;
  mask-image: linear-gradient(to top, #000 8%, rgba(0,0,0,.55) 42%, transparent 82%);
  -webkit-mask-image: linear-gradient(to top, #000 8%, rgba(0,0,0,.55) 42%, transparent 82%);
  opacity: .5;
  animation: gridScroll 2.6s linear infinite;
}
@keyframes gridScroll { to { background-position: 0 74px, 0 0; } }
.ambient-glow { position: absolute; border-radius: 50%; filter: blur(80px); opacity: .5; }
.glow-a { width: 46vw; height: 46vw; min-width: 320px; min-height: 320px; right: -10vw; top: 6vh; background: rgba(53, 230, 255, .16); animation: floatGlow 12s ease-in-out infinite alternate; }
.glow-b { width: 38vw; height: 38vw; min-width: 280px; min-height: 280px; left: -8vw; bottom: 2vh; background: rgba(255, 74, 43, .18); animation: floatGlow 16s ease-in-out infinite alternate-reverse; }
@keyframes floatGlow { to { transform: translate3d(3vw, 4vh, 0) scale(1.12); } }
.ambient-scan {
  position: absolute; inset: 0; opacity: .18;
  background: repeating-linear-gradient(to bottom, transparent 0 3px, rgba(0, 0, 0, .32) 3px 4px);
  mix-blend-mode: multiply;
}

/* ── screens ────────────────────────────────────────────────── */
.screen {
  position: absolute; inset: 0; z-index: 2;
  display: none; flex-direction: column;
  overflow: hidden;
}
.screen.is-active { display: flex; animation: screenIn .42s cubic-bezier(.2, .8, .2, 1) both; }
@keyframes screenIn {
  from { opacity: 0; transform: translateY(14px) scale(.994); }
  to { opacity: 1; transform: none; }
}
.screen.is-leaving { animation: screenOut .26s ease both; }
@keyframes screenOut { to { opacity: 0; transform: translateY(-10px) scale(.996); } }

/* ── generic ────────────────────────────────────────────────── */
.kicker {
  display: flex; align-items: center; gap: 10px;
  font-size: 11px; font-weight: 800; letter-spacing: .24em;
  color: var(--cyan); text-transform: uppercase;
}
.kicker span { width: 22px; height: 2px; background: currentColor; box-shadow: 0 0 12px currentColor; }
.brand-pill {
  display: inline-flex; align-items: center; gap: 9px;
  padding: 9px 14px; border: 1px solid var(--line);
  border-radius: 100px; background: rgba(10, 15, 26, .55);
  font-size: 10px; font-weight: 800; letter-spacing: .16em; color: #b9c4d8;
  backdrop-filter: blur(10px);
}
.brand-pill .sep { color: var(--muted-2); }
.brand-pill.small { padding: 7px 11px; font-size: 9px; }
.live-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--green); box-shadow: 0 0 0 3px rgba(69, 240, 162, .14), 0 0 12px rgba(69, 240, 162, .8); animation: blink 2.2s ease-in-out infinite; }
@keyframes blink { 50% { opacity: .35; } }
.coin-pill {
  display: flex; align-items: center; gap: 7px; padding: 8px 13px;
  border: 1px solid rgba(255, 176, 58, .28); border-radius: 100px;
  background: rgba(255, 176, 58, .07); color: var(--accent-2);
  font-family: var(--font-mono); font-size: 12px; font-weight: 700;
}
.coin-pill .icon { width: 16px; height: 16px; }

.icon-btn {
  width: 42px; height: 42px; display: grid; place-items: center;
  border-radius: 13px; border: 1px solid var(--line);
  background: rgba(13, 19, 32, .62); color: #c9d4e7;
  transition: .18s ease; backdrop-filter: blur(10px);
}
.icon-btn:hover { border-color: var(--line-strong); color: #fff; background: rgba(24, 34, 55, .8); transform: translateY(-1px); }
.icon-btn:active { transform: scale(.94); }
.icon-btn .icon { width: 19px; height: 19px; }

.btn {
  position: relative; display: inline-flex; align-items: center; justify-content: center; gap: 12px;
  min-height: 50px; padding: 0 26px; border-radius: 4px;
  font-size: 13px; font-weight: 900; letter-spacing: .13em; text-transform: uppercase;
  clip-path: polygon(0 0, calc(100% - 13px) 0, 100% 13px, 100% 100%, 13px 100%, 0 calc(100% - 13px));
  transition: transform .16s ease, filter .16s ease, box-shadow .16s ease;
