}
.btn-ghost:hover { border-color: rgba(255,255,255,.34); background: rgba(25, 35, 55, .72); transform: translateY(-2px); }
.btn-xl { min-height: 62px; padding: 0 34px; font-size: 16px; letter-spacing: .18em; }
.btn-xl .icon { width: 22px; height: 22px; transition: transform .2s ease; }
