.ring-1 { border-style: dashed; animation: spin 34s linear infinite; }
.ring-2 { width: 54%; border-color: rgba(255, 74, 43, .16); animation: spin 22s linear infinite reverse; }
@keyframes spin { to { transform: rotate(360deg); } }
.title-art::before {
  content: ""; position: absolute; width: 72%; aspect-ratio: 1; border-radius: 50%;
  background: radial-gradient(circle, rgba(53,230,255,.13), transparent 65%);
  filter: blur(10px);
}
.title-art-label {
  position: absolute; bottom: 4%; left: 50%; transform: translateX(-50%);
  display: flex; align-items: center; gap: 8px; white-space: nowrap;
  font-size: 9px; font-weight: 800; letter-spacing: .18em; color: #94a4bd;
  padding: 7px 12px; border-radius: 100px; border: 1px solid var(--line);
  background: rgba(7, 11, 20, .6); backdrop-filter: blur(8px);
}
.title-art-label .dot { width: 6px; height: 6px; background: var(--cyan); border-radius: 50%; box-shadow: 0 0 9px var(--cyan); }
.title-footer {
  flex: none; display: flex; align-items: center; justify-content: space-between; gap: 20px;
  border-top: 1px solid var(--line); padding-top: 13px; margin-top: 8px;
}
.footer-marquee {
  display: flex; gap: 16px; overflow: hidden; white-space: nowrap;
  font-size: 9px; font-weight: 800; letter-spacing: .18em; color: var(--muted-2);
  mask-image: linear-gradient(90deg, #000 80%, transparent);
  -webkit-mask-image: linear-gradient(90deg, #000 80%, transparent);
}
.footer-marquee i { color: var(--accent); font-style: normal; opacity: .6; }
.build-tag { font-size: 8px; letter-spacing: .16em; color: #465167; white-space: nowrap; }

/* ═══════════════════════════════════════════════════════════════
   MENU
   ═══════════════════════════════════════════════════════════════ */
#screen-menu { padding: calc(18px + var(--safe-t)) clamp(16px, 3.4vw, 46px) calc(12px + var(--safe-b)); }
.menu-header { display: flex; align-items: center; justify-content: space-between; flex: none; padding-bottom: 14px; border-bottom: 1px solid var(--line); }
.menu-brand { display: flex; align-items: center; gap: 16px; }
.mini-logo { font-family: var(--font-display); font-size: 24px; letter-spacing: -.04em; transform: skewX(-6deg); }
.mini-logo span { color: var(--accent); margin-left: 3px; }
.header-right { display: flex; align-items: center; gap: 10px; }
.menu-body {
  flex: 1; min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr) minmax(310px, 372px);
  gap: clamp(18px, 3vw, 42px); width: min(1280px, 100%); margin: 0 auto;
  padding: clamp(16px, 3vh, 34px) 0; align-items: center;
}
.menu-main { min-height: 0; display: flex; flex-direction: column; justify-content: center; }
.menu-intro .kicker { margin-bottom: 13px; }
.menu-intro h2 {
  font-family: var(--font-display); font-size: clamp(40px, 5.6vw, 74px);
  line-height: .9; letter-spacing: -.045em; text-transform: uppercase; transform: skewX(-4deg);
}
.menu-intro h2 em { font-style: normal; color: var(--accent); text-shadow: 0 0 34px rgba(255,74,43,.28); }
.menu-intro p { color: var(--muted); font-size: 13px; margin-top: 14px; max-width: 420px; line-height: 1.5; }
.play-tile {
  margin-top: clamp(18px, 3vh, 30px); position: relative; overflow: hidden;
  display: flex; align-items: center; justify-content: space-between; gap: 18px;
  padding: 20px 22px 20px 26px; text-align: left;
  border: 1px solid rgba(255, 74, 43, .35); border-radius: 16px;
  background:
    radial-gradient(120% 190% at 92% 10%, rgba(255, 74, 43, .28), transparent 55%),
    linear-gradient(110deg, rgba(37, 18, 19, .92), rgba(16, 16, 27, .9));
  box-shadow: 0 18px 46px rgba(0,0,0,.3), inset 0 1px 0 rgba(255,255,255,.07);
  transition: .2s ease;
}
.play-tile::before {
  content: ""; position: absolute; left: 0; top: 0; bottom: 0; width: 4px;
  background: linear-gradient(var(--accent-2), var(--accent));
  box-shadow: 0 0 20px rgba(255,74,43,.8);
}
.play-tile:hover { transform: translateY(-2px); border-color: rgba(255, 74, 43, .6); box-shadow: 0 24px 60px rgba(0,0,0,.4), 0 0 40px rgba(255,74,43,.1); }
.play-tile-copy { display: flex; flex-direction: column; gap: 4px; min-width: 0; }
.play-tile-copy small { font-size: 9px; font-weight: 900; letter-spacing: .24em; color: var(--accent-2); }
.play-tile-copy strong { font-family: var(--font-display); font-size: clamp(22px, 2.6vw, 34px); letter-spacing: -.02em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.play-tile-meta { font-size: 9px; font-weight: 700; letter-spacing: .14em; color: var(--muted); }
.play-tile-go {
  flex: none; width: 58px; height: 58px; border-radius: 50%;
  display: grid; place-items: center; color: #180805;
  background: linear-gradient(140deg, #ffc35c, var(--accent));
  box-shadow: 0 0 0 7px rgba(255, 74, 43, .1), 0 10px 26px rgba(255,74,43,.32);
  transition: .2s ease;
}
.play-tile-go .icon { width: 23px; height: 23px; margin-left: 2px; }
.play-tile:hover .play-tile-go { transform: scale(1.06); box-shadow: 0 0 0 10px rgba(255, 74, 43, .12), 0 12px 32px rgba(255,74,43,.4); }
.menu-tiles { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 12px; }
.menu-tile {
  display: flex; align-items: center; gap: 12px; padding: 13px 14px;
  border: 1px solid var(--line); border-radius: 12px;
  background: rgba(13, 19, 32, .58); text-align: left;
  transition: .18s ease;
}
.menu-tile:hover { border-color: var(--line-strong); background: rgba(24, 34, 54, .72); transform: translateY(-1px); }
.tile-icon { width: 21px; height: 21px; color: var(--cyan); }
.menu-tile span { display: flex; flex-direction: column; gap: 1px; min-width: 0; flex: 1; }
.menu-tile b { font-size: 11px; font-weight: 900; letter-spacing: .1em; }
.menu-tile small { font-size: 9px; color: var(--muted-2); }
.tile-chev { width: 15px; height: 15px; color: var(--muted-2); }
.menu-side { display: flex; flex-direction: column; gap: 14px; min-width: 0; }
.car-panel { padding: 16px 18px 18px; }
.car-panel-art { position: relative; margin: 2px -6px 0; height: clamp(150px, 22vh, 210px); display: grid; place-items: center; }
.car-halo { position: absolute; width: 72%; aspect-ratio: 1; border-radius: 50%; background: radial-gradient(circle, rgba(53,230,255,.15), transparent 68%); filter: blur(6px); }
.car-panel-art .car-svg { width: 112%; transform: rotate(-6deg); filter: drop-shadow(0 22px 22px rgba(0,0,0,.5)); }
.car-panel-name { display: flex; flex-direction: column; gap: 2px; margin-top: 4px; }
.car-panel-name b { font-family: var(--font-display); font-size: 23px; letter-spacing: -.02em; }
.car-panel-name span { font-size: 9px; font-weight: 800; letter-spacing: .18em; color: var(--cyan); }
.stat-bars { display: flex; flex-direction: column; gap: 7px; margin-top: 14px; }
.stat-row { display: grid; grid-template-columns: 48px 1fr 22px; align-items: center; gap: 9px; }
.stat-row label { font-size: 8px; font-weight: 800; letter-spacing: .14em; color: var(--muted); }
.stat-row .track { height: 5px; border-radius: 4px; background: rgba(255,255,255,.07); overflow: hidden; }
.stat-row .track i { display: block; height: 100%; border-radius: inherit; background: linear-gradient(90deg, var(--cyan), var(--lime)); box-shadow: 0 0 10px rgba(53,230,255,.4); }
.stat-row b { font-family: var(--font-mono); font-size: 9px; color: #c8d4e6; text-align: right; }
.record-panel { padding: 15px 18px 17px; }
.record-row { display: flex; align-items: center; gap: 14px; margin-top: 12px; }
.record-time { font-family: var(--font-mono); font-size: clamp(24px, 2.6vw, 32px); font-weight: 700; letter-spacing: -.04em; }
.record-meta { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.record-meta b { font-size: 10px; letter-spacing: .08em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.record-meta span { font-size: 8px; letter-spacing: .16em; color: var(--muted-2); }
.record-stripes { display: flex; gap: 4px; margin-top: 14px; }
.record-stripes i { height: 3px; flex: 1; background: rgba(255,255,255,.1); border-radius: 2px; }
.record-stripes i:nth-child(-n+5) { background: linear-gradient(90deg, var(--accent-2), var(--accent)); box-shadow: 0 0 8px rgba(255,74,43,.3); }
.menu-footer {
  flex: none; display: flex; justify-content: space-between; align-items: center; gap: 20px;
  border-top: 1px solid var(--line); padding-top: 11px;
  font-size: 8px; font-weight: 800; letter-spacing: .16em; color: var(--muted-2);
}
.menu-footer > span:first-child { display: flex; align-items: center; gap: 7px; }

/* ═══════════════════════════════════════════════════════════════
   SUB HEADER (maps / garage)
   ═══════════════════════════════════════════════════════════════ */
.sub-header {
  flex: none; display: flex; align-items: center; gap: 16px;
  padding: calc(16px + var(--safe-t)) clamp(14px, 3vw, 38px) 14px;
  border-bottom: 1px solid var(--line); position: relative; z-index: 3;
  background: linear-gradient(rgba(6,9,16,.7), transparent);
}
.back-btn { width: 44px; height: 44px; }
.sub-title { flex: 1; min-width: 0; }
.sub-title .kicker { margin-bottom: 2px; }
.sub-title h2 { font-family: var(--font-display); font-size: clamp(22px, 3vw, 34px); letter-spacing: -.03em; line-height: 1; }
.random-chip {
  display: inline-flex; align-items: center; gap: 6px; padding: 8px 12px;
  border: 1px solid rgba(53,230,255,.25); border-radius: 100px;
  background: rgba(53,230,255,.06); color: var(--cyan);
  font-size: 8px; font-weight: 900; letter-spacing: .15em;
}
.random-chip .icon { width: 13px; height: 13px; }

/* ═══════════════════════════════════════════════════════════════
   MAP SELECT
   ═══════════════════════════════════════════════════════════════ */
#screen-maps { padding-bottom: calc(100px + var(--safe-b)); }
.maps-scroll { flex: 1; overflow-y: auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: #2b3a52 transparent; }
.map-grid {
  width: min(1280px, 100%); margin: 0 auto; padding: clamp(14px, 2.4vw, 26px) clamp(14px, 3vw, 38px) 24px;
  display: grid; grid-template-columns: repeat(4, 1fr); gap: clamp(10px, 1.6vw, 18px);
}
.map-card {
  position: relative; overflow: hidden; text-align: left;
  aspect-ratio: 4 / 3.05; border-radius: 15px;
  border: 1px solid var(--line); background: #0b111d;
  transition: transform .18s ease, border-color .18s ease, box-shadow .18s ease;
  isolation: isolate;
}
.map-card canvas { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; transition: transform .5s ease; }
.map-card::after {
  content: ""; position: absolute; inset: 0;
  background: linear-gradient(to top, rgba(4,7,13,.95) 0%, rgba(4,7,13,.52) 36%, transparent 68%);
  z-index: 1;
}
.map-card:hover { transform: translateY(-4px); border-color: rgba(255,255,255,.24); box-shadow: 0 20px 46px rgba(0,0,0,.45); }
.map-card:hover canvas { transform: scale(1.055); }
.map-card.is-selected { border-color: var(--accent); box-shadow: 0 0 0 1px var(--accent), 0 16px 42px rgba(255,74,43,.22); }
.map-card.is-selected::before {
  content: ""; position: absolute; inset: 0; z-index: 2; pointer-events: none;
  box-shadow: inset 0 0 0 2px rgba(255, 74, 43, .45), inset 0 0 46px rgba(255, 74, 43, .08);
  border-radius: inherit;
}
.map-index {
  position: absolute; top: 10px; left: 11px; z-index: 3;
  font-family: var(--font-mono); font-size: 9px; font-weight: 700; color: rgba(255,255,255,.8);
  padding: 3px 6px; border-radius: 4px; background: rgba(4,7,13,.45); border: 1px solid rgba(255,255,255,.14);
  backdrop-filter: blur(4px);
}
.map-weather-icons { position: absolute; top: 10px; right: 10px; z-index: 3; display: flex; gap: 4px; }
.map-weather-icons .icon { width: 17px; height: 17px; color: #e8f2ff; filter: drop-shadow(0 1px 3px #000); }
.map-select-mark {
  position: absolute; top: 10px; right: 10px; z-index: 4; width: 22px; height: 22px;
  border-radius: 50%; display: none; place-items: center; background: var(--accent); color: #190703;
}
.map-select-mark .icon { width: 13px; height: 13px; }
.map-card.is-selected .map-select-mark { display: grid; }
.map-card.is-selected .map-weather-icons { display: none; }
.map-body { position: absolute; left: 0; right: 0; bottom: 0; z-index: 3; padding: 11px 13px 12px; }
.map-name { font-family: var(--font-display); font-size: clamp(15px, 1.45vw, 19px); letter-spacing: -.015em; line-height: 1; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.map-sub { display: flex; align-items: center; gap: 7px; margin-top: 4px; font-size: 8px; font-weight: 800; letter-spacing: .13em; color: #9fadc3; white-space: nowrap; overflow: hidden; }
.map-sub .surface { color: var(--cyan); }
.map-sub .dotsep { color: #48546a; }
.map-diff { display: flex; gap: 3px; margin-left: auto; }
.map-diff i { width: 4px; height: 10px; border-radius: 1px; background: rgba(255,255,255,.16); transform: skewX(-12deg); }
.map-diff i.on { background: var(--accent-2); box-shadow: 0 0 6px rgba(255,176,58,.45); }
.map-best { display: flex; align-items: center; gap: 5px; margin-top: 7px; font-family: var(--font-mono); font-size: 8px; color: var(--muted-2); }
.map-best b { color: #dce6f7; font-weight: 700; }
.map-best .new { color: var(--lime); font-family: var(--font-ui); font-weight: 900; letter-spacing: .1em; font-size: 7px; }
.maps-note {
  width: min(1280px, 100%); margin: 0 auto; padding: 0 clamp(14px, 3vw, 38px) 20px;
  display: flex; align-items: center; gap: 8px;
  font-size: 10px; color: var(--muted-2); letter-spacing: .03em;
}
.maps-note .icon { width: 14px; height: 14px; color: var(--accent-2); flex: none; }
.map-footer {
  position: absolute; left: 0; right: 0; bottom: 0; z-index: 5;
  display: flex; align-items: center; justify-content: space-between; gap: 16px;
  padding: 13px clamp(14px, 3vw, 38px) calc(13px + var(--safe-b));
  background: linear-gradient(to top, rgba(5,8,14,.98) 30%, rgba(5,8,14,.82) 70%, transparent);
  border-top: 1px solid rgba(255,255,255,.06);
}
.map-footer-info { display: flex; align-items: center; gap: 12px; min-width: 0; }
.map-footer-thumb { width: 52px; height: 42px; border-radius: 8px; border: 1px solid var(--line-strong); background: #101827 center/cover; flex: none; overflow: hidden; }
.map-footer-thumb canvas { width: 100%; height: 100%; display: block; }
.map-footer-info > div:last-child { display: flex; flex-direction: column; gap: 1px; min-width: 0; }
.map-footer-info small { font-size: 7px; font-weight: 800; letter-spacing: .18em; color: var(--muted-2); }
.map-footer-info b { font-family: var(--font-display); font-size: 16px; letter-spacing: -.01em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.map-footer-info span { font-size: 8px; font-weight: 700; letter-spacing: .1em; color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.btn-race { min-height: 54px; padding: 0 40px; font-size: 14px; }

/* ═══════════════════════════════════════════════════════════════
   GARAGE
   ═══════════════════════════════════════════════════════════════ */
#screen-garage { padding-bottom: calc(20px + var(--safe-b)); }
.garage-scroll { flex: 1; overflow-y: auto; overscroll-behavior: contain; }
.garage-grid {
  width: min(1200px, 100%); margin: 0 auto; padding: clamp(18px, 3vw, 34px) clamp(14px, 3vw, 38px) 20px;
  display: grid; grid-template-columns: repeat(2, 1fr); gap: clamp(12px, 2vw, 20px);
}
.garage-card {
  position: relative; overflow: hidden; border-radius: 18px; text-align: left;
  border: 1px solid var(--line); background: linear-gradient(155deg, rgba(23,32,52,.82), rgba(9,13,23,.92));
  padding: 18px; transition: .2s ease; min-height: 250px;
}
.garage-card::before {
  content: ""; position: absolute; inset: 0; pointer-events: none;
  background: radial-gradient(80% 60% at 50% 28%, color-mix(in srgb, var(--car-color) 18%, transparent), transparent 70%);
}
.garage-card:hover { transform: translateY(-3px); border-color: var(--line-strong); }
.garage-card.is-selected { border-color: var(--car-color); box-shadow: 0 0 0 1px var(--car-color), 0 18px 50px rgba(0,0,0,.4); }
.garage-card-top { position: relative; display: flex; justify-content: space-between; align-items: flex-start; z-index: 2; }
.garage-card-top small { font-size: 8px; font-weight: 800; letter-spacing: .17em; color: var(--muted-2); }
.garage-card-top b { display: block; font-family: var(--font-display); font-size: clamp(18px, 2vw, 25px); letter-spacing: -.02em; margin-top: 2px; }
.garage-class { font-size: 8px; font-weight: 900; letter-spacing: .14em; padding: 5px 8px; border-radius: 5px; border: 1px solid color-mix(in srgb, var(--car-color) 40%, transparent); color: var(--car-color); background: color-mix(in srgb, var(--car-color) 9%, transparent); white-space: nowrap; }
.garage-art { position: relative; height: 128px; margin: 0 -10px; display: grid; place-items: center; z-index: 1; }
.garage-art .car-svg { width: 82%; transform: rotate(-6deg); filter: drop-shadow(0 16px 18px rgba(0,0,0,.5)); }
.garage-stats { position: relative; z-index: 2; display: flex; flex-direction: column; gap: 5px; }
.garage-actions { position: relative; z-index: 2; display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-top: 12px; }
.garage-pick { font-size: 9px; font-weight: 900; letter-spacing: .13em; padding: 9px 14px; border-radius: 6px; background: rgba(255,255,255,.08); border: 1px solid var(--line-strong); }
.garage-card.is-selected .garage-pick { background: var(--car-color); color: #150704; border-color: transparent; }
.garage-desc { font-size: 9px; line-height: 1.4; color: var(--muted); max-width: 62%; }
.garage-tip {
  width: min(1200px, 100%); margin: 0 auto; padding: 0 clamp(14px, 3vw, 38px) 16px;
  display: flex; align-items: center; gap: 8px; font-size: 10px; color: var(--muted-2);
}
.garage-tip .icon { width: 14px; height: 14px; color: var(--accent-2); }

/* ═══════════════════════════════════════════════════════════════
   RACE
   ═══════════════════════════════════════════════════════════════ */
.race-screen { background: #05080f; touch-action: none; }
#game { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
.hud { position: absolute; inset: 0; pointer-events: none; z-index: 4; font-family: var(--font-ui); }
.hud-top {
  position: absolute; top: calc(12px + var(--safe-t)); left: 14px; right: 14px;
  display: flex; align-items: flex-start; gap: 10px;
  padding: 9px 12px; border-radius: 14px;
  background: linear-gradient(180deg, rgba(5,8,14,.58), rgba(5,8,14,.18));
  border: 1px solid rgba(255,255,255,.07); backdrop-filter: blur(8px);
}
.hud-block { display: flex; flex-direction: column; gap: 1px; min-width: 52px; }
.hud-block small, .hud-weather small { font-size: 7px; font-weight: 900; letter-spacing: .18em; color: #97a6bd; }
.hud-lap, .hud-position { display: flex; align-items: baseline; gap: 1px; font-family: var(--font-mono); line-height: 1; }
.hud-lap b, .hud-position b { font-size: clamp(22px, 3vw, 30px); font-weight: 800; letter-spacing: -.06em; }
.hud-lap span, .hud-position span { font-size: 11px; color: #8d9bb2; font-weight: 700; }
.lap-dots { display: flex; gap: 3px; margin-top: 3px; }
.lap-dots i { width: 12px; height: 3px; border-radius: 2px; background: rgba(255,255,255,.16); }
.lap-dots i.on { background: var(--accent); box-shadow: 0 0 8px rgba(255,74,43,.6); }
.hud-timer { position: absolute; left: 50%; top: 9px; transform: translateX(-50%); text-align: center; }
.hud-time { font-family: var(--font-mono); font-size: clamp(20px, 2.6vw, 27px); font-weight: 700; letter-spacing: -.05em; line-height: 1; text-shadow: 0 2px 12px rgba(0,0,0,.6); }
.hud-laptime { display: flex; align-items: center; justify-content: center; gap: 5px; margin-top: 4px; font-size: 7px; font-weight: 900; letter-spacing: .16em; color: #95a4bb; }
.hud-laptime b { font-family: var(--font-mono); font-size: 9px; letter-spacing: 0; color: #d9e3f2; }
.hud-weather {
  margin-left: auto; display: flex; align-items: center; gap: 8px;
  padding: 5px 10px 5px 7px; border-radius: 9px;
  background: rgba(255,255,255,.05); border: 1px solid rgba(255,255,255,.08);
  min-width: 92px;
}
.weather-icon { width: 20px; height: 20px; color: var(--cyan); }
.hud-weather > div { display: flex; flex-direction: column; gap: 0; min-width: 0; }
.hud-weather b { font-size: 9px; font-weight: 900; letter-spacing: .08em; white-space: nowrap; }
.pause-btn { pointer-events: auto; width: 36px; height: 36px; border-radius: 9px; }
.pause-btn .icon { width: 16px; height: 16px; }
.hud-minimap {
  position: absolute; top: calc(78px + var(--safe-t)); right: 14px;
  width: 116px; padding: 7px; border-radius: 13px;
  background: rgba(6,10,18,.52); border: 1px solid rgba(255,255,255,.09);
  backdrop-filter: blur(6px);
}
.hud-minimap canvas { width: 100%; height: auto; display: block; }
.minimap-label { margin-top: 3px; text-align: center; font-size: 6px; font-weight: 900; letter-spacing: .13em; color: #9cabc0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.hud-speed {
  position: absolute; left: 18px; bottom: calc(122px + var(--safe-b));
  min-width: 132px; padding: 8px 12px 9px;
  background: linear-gradient(100deg, rgba(5,8,14,.68), rgba(5,8,14,.28));
