}
.speed-number { display: flex; align-items: baseline; gap: 5px; line-height: .9; }
.speed-number b { font-family: var(--font-mono); font-size: clamp(30px, 4.4vw, 42px); font-weight: 800; letter-spacing: -.08em; font-variant-numeric: tabular-nums; }
.speed-number span { font-size: 8px; font-weight: 900; letter-spacing: .12em; color: #98a7bd; }
.speed-bar { height: 3px; border-radius: 2px; background: rgba(255,255,255,.14); margin-top: 5px; overflow: hidden; }
.speed-bar i { display: block; height: 100%; width: 0%; background: linear-gradient(90deg, var(--cyan), var(--lime) 60%, var(--accent)); border-radius: inherit; transition: width .1s linear; }
.hud-boost {
  position: absolute; left: 50%; bottom: calc(122px + var(--safe-b)); transform: translateX(-50%);
  width: min(230px, 34vw); padding: 6px 9px 8px; border-radius: 8px;
  background: rgba(5,8,14,.56); border: 1px solid rgba(255,255,255,.08); backdrop-filter: blur(6px);
}
.boost-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 4px; }
.boost-head span { font-size: 7px; font-weight: 900; letter-spacing: .2em; color: var(--cyan); }
.boost-head b { font-family: var(--font-mono); font-size: 8px; color: #b8c6da; }
.boost-track { position: relative; height: 8px; border-radius: 4px; background: rgba(255,255,255,.1); overflow: hidden; }
.boost-track i { display: block; height: 100%; width: 100%; border-radius: inherit; background: linear-gradient(90deg, #0f9db8, var(--cyan) 48%, #eaffff 80%, var(--accent-2)); box-shadow: 0 0 12px rgba(53,230,255,.55); transition: width .1s linear; }
.boost-track em { position: absolute; top: 0; bottom: 0; width: 1px; background: rgba(3,8,14,.5); }
.boost-track em:nth-of-type(1) { left: 25%; } .boost-track em:nth-of-type(2) { left: 50%; } .boost-track em:nth-of-type(3) { left: 75%; }
.hud-progress { position: absolute; left: 50%; top: calc(63px + var(--safe-t)); transform: translateX(-50%); width: min(260px, 38vw); display: flex; flex-direction: column; align-items: center; gap: 3px; }
.progress-track { width: 100%; height: 2px; background: rgba(255,255,255,.15); border-radius: 2px; overflow: hidden; }
.progress-track i { display: block; width: 0%; height: 100%; background: linear-gradient(90deg, var(--cyan), var(--lime)); box-shadow: 0 0 8px rgba(53,230,255,.5); transition: width .12s linear; }
.hud-progress span { font-size: 6px; font-weight: 900; letter-spacing: .18em; color: #a3b1c5; }
.drift-badge {
  position: absolute; left: 50%; bottom: calc(184px + var(--safe-b)); transform: translateX(-50%) scale(.85);
  font-family: var(--font-display); font-size: 15px; letter-spacing: .02em; color: var(--cyan);
  text-shadow: 0 0 18px rgba(53,230,255,.7); opacity: 0; transition: .15s ease;
  display: flex; align-items: baseline; gap: 6px;
}
.drift-badge b { font-family: var(--font-ui); font-size: 8px; letter-spacing: .12em; color: var(--lime); }
.drift-badge.show { opacity: 1; transform: translateX(-50%) scale(1); }
.offroad-warn {
  position: absolute; left: 50%; top: 34%; transform: translate(-50%, -50%) scale(.9);
  font-family: var(--font-display); font-size: clamp(20px, 3vw, 30px); color: var(--accent);
  text-shadow: 0 2px 0 rgba(0,0,0,.5), 0 0 28px rgba(255,74,43,.5); letter-spacing: .05em;
  opacity: 0; transition: .15s ease;
}
.offroad-warn.show { opacity: 1; transform: translate(-50%, -50%) scale(1); animation: warnPulse .6s ease infinite alternate; }
@keyframes warnPulse { to { opacity: .5; } }
.race-banner {
  position: absolute; top: 24%; left: 50%; transform: translate(-50%, -14px);
  z-index: 6; display: flex; flex-direction: column; align-items: center; gap: 2px;
