}
.race-banner.show { opacity: 1; transform: translate(-50%, 0); }
.race-banner small { font-size: 7px; font-weight: 900; letter-spacing: .25em; color: var(--cyan); }
.race-banner b { font-family: var(--font-display); font-size: 17px; letter-spacing: .02em; }
.countdown {
  position: absolute; inset: 0; z-index: 7; display: grid; place-items: center;
  pointer-events: none; opacity: 0;
}
.countdown.show { opacity: 1; }
.countdown span {
  font-family: var(--font-display); font-size: clamp(100px, 19vw, 230px); line-height: 1;
  color: #fff; letter-spacing: -.05em;
