}
.countdown.go span { color: var(--lime); text-shadow: 0 0 70px rgba(214,255,75,.6), 0 10px 0 rgba(0,0,0,.25); font-size: clamp(80px, 15vw, 180px); }
@keyframes countPop { from { transform: scale(1.7); opacity: 0; } 60% { opacity: 1; } to { transform: scale(1); opacity: 1; } }
.race-flash { position: absolute; inset: 0; z-index: 3; background: #fff; opacity: 0; pointer-events: none; }
.race-flash.flash { animation: flashOut .35s ease-out; }
