.modal-root {
  position: absolute; inset: 0; z-index: 40; display: none; place-items: center;
  padding: 18px; background: rgba(3, 6, 11, .7); backdrop-filter: blur(8px);
}
.modal-root.open { display: grid; animation: fadeIn .2s ease both; }
@keyframes fadeIn { from { opacity: 0; } }
