.setting-row { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 12px 0; border-bottom: 1px solid var(--line); }
.setting-row:last-of-type { border-bottom: 0; }
.setting-row > div { display: flex; flex-direction: column; gap: 2px; }
.setting-row b { font-size: 12px; }
.setting-row small { font-size: 9px; color: var(--muted-2); }
.switch { width: 46px; height: 26px; border-radius: 20px; background: rgba(255,255,255,.12); border: 1px solid var(--line-strong); position: relative; transition: .2s ease; flex: none; }
.switch::after { content: ""; position: absolute; top: 3px; left: 3px; width: 18px; height: 18px; border-radius: 50%; background: #7d8ba1; transition: .2s ease; }
.switch.on { background: rgba(53,230,255,.22); border-color: rgba(53,230,255,.5); }
