/* ═══════════════════════════════════════════════════════════════
   RC RUSH — procedural track builder
   Pseudo-3D segment road with seeded random layouts.
   ═══════════════════════════════════════════════════════════════ */

export const SEGMENT_LENGTH = 200;
export const ROAD_WIDTH = 1000;
export const DRAW_DISTANCE = 180;

export function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const easeIn = (a, b, p) => a + (b - a) * Math.pow(p, 2);
const easeInOut = (a, b, p) => a + (b - a) * (-Math.cos(p * Math.PI) / 2 + 0.5);
const pick = (rng, arr) => arr[Math.floor(rng() * arr.length) % arr.length];

export function generateTrack(location, seed = Date.now()) {
  const rng = mulberry32(seed);
  const segments = [];
  let currentY = 0;

  const addSegment = (curve, y) => {
    const n = segments.length;
    segments.push({
      index: n,
      curve,
      y,
      props: [],
      wet: false,
      p1: { world: { y: 0, z: n * SEGMENT_LENGTH }, camera: {}, screen: {} },
      p2: { world: { y: 0, z: (n + 1) * SEGMENT_LENGTH }, camera: {}, screen: {} }
    });
    // fill y values (p1 = previous point y)
    const prevY = n === 0 ? y : segments[n - 1].y;
    segments[n].p1.world.y = prevY;
    segments[n].p2.world.y = y;
  };

  const addRoad = (enter, hold, leave, curve, hill) => {
    const startY = currentY;
    const endY = startY + hill * SEGMENT_LENGTH;
    const total = Math.max(1, enter + hold + leave);
    for (let n = 0; n < enter; n++) addSegment(easeIn(0, curve, n / Math.max(1, enter)), easeInOut(startY, endY, n / total));
    for (let n = 0; n < hold; n++) addSegment(curve, easeInOut(startY, endY, (enter + n) / total));
    for (let n = 0; n < leave; n++) addSegment(easeInOut(curve, 0, n / Math.max(1, leave)), easeInOut(startY, endY, (enter + hold + n) / total));
    currentY = endY;
  };

  // opening straight
  addRoad(10, 42, 10, 0, 0);

  const sectionCount = 9 + Math.floor(rng() * 4); // 9–12
  const diff = location.difficulty;
  for (let s = 0; s < sectionCount; s++) {
    const isSCurve = rng() < 0.24;
    const isHairpin = !isSCurve && rng() < 0.13 + diff * 0.01;
    const dir = rng() < 0.5 ? -1 : 1;

    let curve = (1.5 + rng() * 2.6) * dir;
    if (isHairpin) curve = (4.2 + rng() * 1.1) * dir;
    curve *= 0.86 + diff * 0.045;

    let hill = (rng() * 2 - 1) * (14 + diff * 3.2);
    if (Math.abs(currentY) > 14000) hill = -Math.sign(currentY) * (10 + rng() * 14);
    if (Math.abs(currentY) > 24000) hill = -Math.sign(currentY) * 28;

    const scale = 0.8 + rng() * 0.55;
    const enter = Math.round((16 + rng() * 24) * scale);
    const hold = Math.round((20 + rng() * 46) * scale);
    const leave = Math.round((16 + rng() * 24) * scale);

    if (isSCurve) {
      const c = 2.2 + rng() * 2.2;
      addRoad(enter, hold, 8, c * dir, hill);
      addRoad(8, hold * 0.85, leave, -c * dir, -hill * 0.4);
    } else {
      addRoad(enter, hold, leave, curve, hill);
    }

    // occasional short breather / crest
    if (rng() < 0.35) {
      addRoad(10, 18 + Math.floor(rng() * 20), 10, 0, (rng() * 2 - 1) * (8 + diff * 2));
    }
  }

  // bring elevation back to zero for a seamless loop
  if (Math.abs(currentY) > 120) {
    const hill = -currentY / SEGMENT_LENGTH;
    addRoad(24, 46, 24, 0, hill);
  }
  // closing straight
  addRoad(8, 38, 8, 0, 0);

  // guarantee enough track
  while (segments.length < 900) addRoad(10, 40, 10, (rng() * 2 - 1) * 2.4, (rng() * 2 - 1) * 8);

  const total = segments.length;
  const length = total * SEGMENT_LENGTH;

  // ── props & scenery ─────────────────────────────────────────
  const markerTypes = { neon: 'lamp', dunes: 'flag', frost: 'flag', coast: 'buoy', redwood: 'sign', magma: 'vent', glacier: 'flag', dockyard: 'barrel', sunset: 'lamp', bayou: 'firefly', toy: 'block', orbital: 'sign' };

  for (let i = 6; i < total - 4; i++) {
    const seg = segments[i];
    const density = location.density;
    if (rng() < density) {
      const side = rng() < 0.5 ? -1 : 1;
      const type = pick(rng, location.props);
      const isBuilding = type === 'building' || type === 'container' || type === 'crane';
      const offset = side * (isBuilding ? 2.0 + rng() * 2.4 : 1.32 + rng() * 2.1);
      seg.props.push({
        type,
        offset,
        size: 0.72 + rng() * 1.15,
        seed: Math.floor(rng() * 100000),
        side
      });
    }
    // marker lights / edge furniture
    if (i % 11 === 0) {
      const side = i % 22 === 0 ? -1 : 1;
      seg.props.push({
        type: markerTypes[location.id] || 'flag',
        offset: side * 1.18,
        size: 0.34 + rng() * 0.12,
        seed: Math.floor(rng() * 100000),
        side,
        marker: true
      });
    }
  }

  // start gantry and finish strip
  segments[2].props.push({ type: 'gantry', offset: 0, size: 1.55, seed: 7, side: 0 });
  segments[2].props.push({ type: 'startlight', offset: 0.62, size: 0.55, seed: 9, side: 0 });
  for (let i = 0; i < 3; i++) segments[i].finish = true;

  // puddles / wet patches
  for (let i = 0; i < 26; i++) {
    const idx = Math.floor(rng() * total);
    segments[idx].wet = true;
    segments[idx].wetSeed = rng();
  }

  // boost pads
  const boostPads = [];
  const padCount = 7 + Math.floor(rng() * 3);
  for (let k = 0; k < padCount; k++) {
    const idx = Math.floor((k + 0.55 + rng() * 0.35) * total / padCount) % total;
    boostPads.push({ index: idx, x: (rng() * 1.35 - 0.675), active: true, cooldown: 0, phase: rng() * Math.PI * 2 });
  }

  // ── minimap path ────────────────────────────────────────────
  const points = [];
  let hx = 0, hy = 0, heading = 0;
  for (let i = 0; i < total; i += 3) {
    points.push({ x: hx, y: hy });
    heading += segments[i].curve * 0.0072;
    hx += Math.cos(heading);
    hy += Math.sin(heading);
  }
  // close path gently
  points.push({ x: 0, y: 0 });

  let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
  for (const p of points) {
    if (p.x < minX) minX = p.x; if (p.x > maxX) maxX = p.x;
    if (p.y < minY) minY = p.y; if (p.y > maxY) maxY = p.y;
  }
  const spanX = Math.max(1, maxX - minX), spanY = Math.max(1, maxY - minY);
  const span = Math.max(spanX, spanY);
  const cx = (minX + maxX) / 2, cy = (minY + maxY) / 2;
  const norm = points.map(p => ({ x: 0.5 + (p.x - cx) / span, y: 0.5 + (p.y - cy) / span }));

  return {
    location,
    seed,
    segments,
    total,
    length,
    segmentLength: SEGMENT_LENGTH,
    roadWidth: ROAD_WIDTH,
    boostPads,
    minimap: norm,
    laps: 3
  };
}

export function segmentAt(track, z) {
  const total = track.length;
  let pos = z % total;
  if (pos < 0) pos += total;
  return track.segments[Math.floor(pos / track.segmentLength) % track.total];
}

export function curveAt(track, z) {
  return segmentAt(track, z).curve / 5;
}

export function percentRemaining(n, total) {
  return (n % total) / total;
}

export function interpolate(a, b, p) {
  return a + (b - a) * p;
}

export function wrapPosition(z, length) {
  let v = z % length;
  if (v < 0) v += length;
  return v;
}

export function formatTime(seconds, showMinutes = true) {
  if (!isFinite(seconds) || seconds < 0) seconds = 0;
  const m = Math.floor(seconds / 60);
  const s = Math.floor(seconds % 60);
  const cs = Math.floor((seconds % 1) * 100);
  if (!showMinutes) return `${String(s).padStart(2, '0')}.${String(cs).padStart(2, '0')}`;
  return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}.${String(cs).padStart(2, '0')}`;
}

/* ═══════════════════════════════════════════════════════════════
   RC RUSH — dynamic weather system
   ═══════════════════════════════════════════════════════════════ */
import { WEATHER } from './data.js';

const lerp = (a, b, t) => a + (b - a) * t;
const smooth = t => t * t * (3 - 2 * t);

export class WeatherSystem {
  constructor(location, onChange = null) {
    this.location = location;
    this.onChange = onChange;
    this.reset();
  }

  reset() {
    const pool = this.location.weather;
    this.type = pool[Math.floor(Math.random() * pool.length)];
    this.prev = this.type;
    this.blend = 1;
    this.timer = 18 + Math.random() * 12;
    this.flash = 0;
    this.justChanged = null;
    this.races = 0;
    this.totalTime = 0;
  }

  update(dt) {
    this.totalTime += dt;
    this.timer -= dt;
    this.flash = Math.max(0, this.flash - dt * 1.6);

    if (this.blend < 1) this.blend = Math.min(1, this.blend + dt / 4.2);

    if (this.timer <= 0 && this.blend >= 1) {
      const pool = this.location.weather;
      const options = pool.filter(w => w !== this.type);
      const next = options.length ? options[Math.floor(Math.random() * options.length)] : pool[0];
      this.prev = this.type;
      this.type = next;
      this.blend = 0;
      this.timer = 18 + Math.random() * 14;
      this.justChanged = WEATHER[next];
      if (this.onChange) this.onChange(WEATHER[next]);
    }

    const cur = WEATHER[this.type];
    if (cur.lightning && Math.random() < dt * 0.22) this.flash = 1;
  }

  params() {
    const a = WEATHER[this.prev];
    const b = WEATHER[this.type];
    const t = smooth(this.blend);
    return {
      grip: lerp(a.grip, b.grip, t),
      fog: lerp(a.fog, b.fog, t),
      particles: lerp(a.particles, b.particles, t),
      tintAlpha: lerp(a.tintAlpha, b.tintAlpha, t),
      tint: t < 0.5 ? a.tint : b.tint,
      wind: lerp(a.wind, b.wind, t),
      skyDim: lerp(a.skyDim, b.skyDim, t),
      kind: t < 0.55 ? a.kind : b.kind,
      lightning: (t < 0.5 ? a : b).lightning,
      label: (t < 0.5 ? a : b).label,
      icon: (t < 0.5 ? a : b).icon,
      id: (t < 0.5 ? a : b).id,
      from: a, to: b, blend: t
    };
  }

  get current() { return WEATHER[this.type]; }
}

/* ═══════════════════════════════════════════════════════════════
   RC RUSH — input (touch buttons + keyboard)
   ═══════════════════════════════════════════════════════════════ */

export class Input {
  constructor() {
    this.left = false;
    this.right = false;
    this.brake = false;
    this.boost = false;
    this.steer = 0;
    this.steerTarget = 0;
    this.enabled = false;
    this.onPause = null;
    this.onAny = null;
    this.pointers = new Map();
    this.buttons = [];
    this.keyMap = new Map();
    this._bindKeys();
  }

  _bindKeys() {
    const down = e => {
      if (!this.enabled) return;
      const k = e.key.toLowerCase();
      if (['arrowleft', 'a', 'arrowright', 'd', 'arrowdown', 's', ' ', 'shift', 'escape', 'p'].includes(k)) e.preventDefault();
      if (k === 'escape' || k === 'p') { if (this.onPause) this.onPause(); return; }
      if (k === 'arrowleft' || k === 'a') this.left = true;
      if (k === 'arrowright' || k === 'd') this.right = true;
      if (k === 'arrowdown' || k === 's' || k === 'shift') this.brake = true;
      if (k === ' ' || k === 'arrowup' || k === 'w') this.boost = true;
      if (this.onAny) this.onAny();
    };
    const up = e => {
      const k = e.key.toLowerCase();
      if (k === 'arrowleft' || k === 'a') this.left = false;
      if (k === 'arrowright' || k === 'd') this.right = false;
      if (k === 'arrowdown' || k === 's' || k === 'shift') this.brake = false;
      if (k === ' ' || k === 'arrowup' || k === 'w') this.boost = false;
    };
    window.addEventListener('keydown', down, { passive: false });
    window.addEventListener('keyup', up);
    window.addEventListener('blur', () => this.releaseAll());
  }

  bindButtons(root = document) {
    this.buttons = [...root.querySelectorAll('[data-action]')];
    for (const btn of this.buttons) {
      const action = btn.dataset.action;
      const press = e => {
        if (!this.enabled) return;
        e.preventDefault();
        btn.classList.add('pressed');
        try { btn.setPointerCapture(e.pointerId); } catch { /* ignore */ }
        this.pointers.set(e.pointerId, action);
        this._setAction(action, true);
        if (this.onAny) this.onAny();
      };
      const release = e => {
        const act = this.pointers.get(e.pointerId);
        if (act) {
          this.pointers.delete(e.pointerId);
          const still = [...this.pointers.values()].includes(act);
          if (!still) {
            btn.classList.remove('pressed');
            this._setAction(act, false);
          }
        } else {
          btn.classList.remove('pressed');
          this._setAction(action, false);
        }
      };
      btn.addEventListener('pointerdown', press);
      btn.addEventListener('pointerup', release);
      btn.addEventListener('pointercancel', release);
      btn.addEventListener('lostpointercapture', release);
      btn.addEventListener('contextmenu', e => e.preventDefault());
    }
  }

  _setAction(action, on) {
    if (action === 'left') this.left = on;
    if (action === 'right') this.right = on;
    if (action === 'brake') this.brake = on;
    if (action === 'boost') this.boost = on;
  }

  update(dt) {
    this.steerTarget = (this.right ? 1 : 0) - (this.left ? 1 : 0);
    const rate = this.steerTarget === 0 ? 11 : 9.5;
    this.steer += (this.steerTarget - this.steer) * Math.min(1, dt * rate);
    if (Math.abs(this.steer) < 0.002) this.steer = 0;
    return this.steer;
  }

  releaseAll() {
    this.left = this.right = this.brake = this.boost = false;
    this.pointers.clear();
    for (const b of this.buttons) b.classList.remove('pressed');
  }

  reset() {
    this.releaseAll();
    this.steer = 0;
    this.steerTarget = 0;
  }
}

/* ═══════════════════════════════════════════════════════════════
   RC RUSH — procedural WebAudio engine, skids, weather & music
   ═══════════════════════════════════════════════════════════════ */

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.ready = false;
    this.sound = true;
    this.music = true;
    this.engineGain = null;
    this.engineOsc = null;
    this.engineSub = null;
    this.engineFilter = null;
    this.windGain = null;
    this.skidGain = null;
    this.master = null;
    this.musicGain = null;
    this.noise = null;
    this.step = 0;
    this.nextNoteTime = 0;
    this.musicOn = false;
    this.root = 110;
    this.raceActive = false;
    this.lastSpeed = 0;
  }

  ensure() {
    if (this.ready) return this.ctx;
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return null;
    try {
      this.ctx = new AC();
      this.master = this.ctx.createGain();
      this.master.gain.value = this.sound ? 0.8 : 0;
      this.master.connect(this.ctx.destination);

      this.musicGain = this.ctx.createGain();
      this.musicGain.gain.value = this.music ? 0.16 : 0;
      this.musicGain.connect(this.master);

      // engine bus
      this.engineFilter = this.ctx.createBiquadFilter();
      this.engineFilter.type = 'lowpass';
      this.engineFilter.frequency.value = 520;
      this.engineFilter.Q.value = 4;
      this.engineGain = this.ctx.createGain();
      this.engineGain.gain.value = 0;
      this.engineFilter.connect(this.engineGain);
      this.engineGain.connect(this.master);

      this.engineOsc = this.ctx.createOscillator();
      this.engineOsc.type = 'sawtooth';
      this.engineOsc.frequency.value = 70;
      this.engineOsc.connect(this.engineFilter);
      this.engineOsc.start();

      this.engineSub = this.ctx.createOscillator();
      this.engineSub.type = 'square';
      this.engineSub.frequency.value = 35;
      const subGain = this.ctx.createGain();
      subGain.gain.value = 0.35;
      this.engineSub.connect(subGain);
      subGain.connect(this.engineFilter);
      this.engineSub.start();

      // noise buffer
      const len = this.ctx.sampleRate * 2;
      const buffer = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
      const data = buffer.getChannelData(0);
      for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
      this.noise = buffer;

      // wind
      const windSrc = this.ctx.createBufferSource();
      windSrc.buffer = buffer; windSrc.loop = true;
      const windFilter = this.ctx.createBiquadFilter();
      windFilter.type = 'bandpass'; windFilter.frequency.value = 650; windFilter.Q.value = 0.6;
      this.windGain = this.ctx.createGain(); this.windGain.gain.value = 0;
      windSrc.connect(windFilter); windFilter.connect(this.windGain); this.windGain.connect(this.master);
      windSrc.start();

      // skid
      const skidSrc = this.ctx.createBufferSource();
      skidSrc.buffer = buffer; skidSrc.loop = true;
      const skidFilter = this.ctx.createBiquadFilter();
      skidFilter.type = 'bandpass'; skidFilter.frequency.value = 1900; skidFilter.Q.value = 2.4;
      this.skidGain = this.ctx.createGain(); this.skidGain.gain.value = 0;
      skidSrc.connect(skidFilter); skidFilter.connect(this.skidGain); this.skidGain.connect(this.master);
      skidSrc.start();

      this.ready = true;
      return this.ctx;
    } catch {
      this.ready = false;
      return null;
    }
  }

  async unlock() {
    const ctx = this.ensure();
    if (ctx && ctx.state === 'suspended') { try { await ctx.resume(); } catch { /* ignore */ } }
  }

  setSettings({ sound, music }) {
    this.sound = sound; this.music = music;
    if (!this.ready) return;
    const now = this.ctx.currentTime;
    this.master.gain.cancelScheduledValues(now);
    this.master.gain.linearRampToValueAtTime(sound ? 0.8 : 0, now + 0.12);
    this.musicGain.gain.cancelScheduledValues(now);
    this.musicGain.gain.linearRampToValueAtTime(music ? 0.16 : 0, now + 0.2);
  }

  startRace() {
    this.raceActive = true;
    this.ensure();
    if (!this.ready) return;
    const now = this.ctx.currentTime;
    this.engineGain.gain.cancelScheduledValues(now);
    this.engineGain.gain.setTargetAtTime(0.05, now, 0.2);
    this.musicOn = true;
    this.nextNoteTime = now + 0.15;
    this.step = 0;
  }

  stopRace() {
    this.raceActive = false;
    if (!this.ready) return;
    const now = this.ctx.currentTime;
    this.engineGain.gain.setTargetAtTime(0, now, 0.25);
    this.windGain.gain.setTargetAtTime(0, now, 0.25);
    this.skidGain.gain.setTargetAtTime(0, now, 0.2);
    this.musicOn = false;
  }

  pauseRace(paused) {
    if (!this.ready) return;
    const now = this.ctx.currentTime;
    this.engineGain.gain.setTargetAtTime(paused ? 0 : 0.05, now, 0.15);
    this.musicOn = !paused;
    if (!paused) this.nextNoteTime = Math.max(this.nextNoteTime, now + 0.1);
  }

  setTheme(index) {
    const roots = [110, 98, 130.8, 123.5, 87.3, 82.4, 116.5, 103.8, 92.5, 146.8, 138.6, 73.4];
    this.root = roots[index % roots.length];
  }

  update(dt, speedRatio = 0, boosting = false, offroad = false, drifting = 0) {
    if (!this.ready) return;
    const now = this.ctx.currentTime;
    const ratio = Math.max(0, Math.min(1.3, speedRatio));
    const targetFreq = 52 + ratio * 170 + (boosting ? 34 : 0);
    this.engineOsc.frequency.setTargetAtTime(targetFreq, now, 0.04);
    this.engineSub.frequency.setTargetAtTime(targetFreq * 0.5, now, 0.05);
    this.engineFilter.frequency.setTargetAtTime(380 + ratio * 1150 + (boosting ? 700 : 0), now, 0.06);
    const base = this.raceActive ? 0.036 + ratio * 0.028 : 0;
    this.engineGain.gain.setTargetAtTime(base + (boosting ? 0.018 : 0), now, 0.08);
    this.windGain.gain.setTargetAtTime(this.raceActive ? ratio * 0.025 + (offroad ? 0.03 : 0) : 0, now, 0.12);
    this.skidGain.gain.setTargetAtTime(this.raceActive ? drifting * 0.05 + (offroad ? 0.028 : 0) : 0, now, 0.07);

    if (this.musicOn && this.music) this._scheduleMusic(now);
  }

  _scheduleMusic(now) {
    if (this.nextNoteTime < now) this.nextNoteTime = now + 0.05;
    const stepDur = 0.19;
    while (this.nextNoteTime < now + 0.25) {
      const t = this.nextNoteTime;
      const seq = [0, 7, 3, 10, 5, 12, 7, 3, 0, 7, 10, 15, 12, 10, 7, 3];
      const note = seq[this.step % seq.length];
      const freq = this.root * Math.pow(2, note / 12);
      this._pluck(freq, t, 0.14, 0.055, 'triangle');
      if (this.step % 4 === 0) this._pluck(this.root / 2, t, 0.34, 0.075, 'sine');
      if (this.step % 8 === 4) this._pluck(this.root * 1.5, t, 0.2, 0.035, 'sine');
      this.nextNoteTime += stepDur;
      this.step++;
    }
  }

  _pluck(freq, t, dur, vol, type = 'triangle') {
    if (!this.ready) return;
    const osc = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(vol, t + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    osc.connect(g); g.connect(this.musicGain);
    osc.start(t); osc.stop(t + dur + 0.02);
  }

  beep(freq = 660, dur = 0.12, vol = 0.18, type = 'square') {
    this.ensure();
    if (!this.ready || !this.sound) return;
    const t = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    osc.type = type; osc.frequency.value = freq;
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(vol, t + 0.01);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    osc.connect(g); g.connect(this.master);
    osc.start(t); osc.stop(t + dur + 0.03);
  }

  countdown(n) {
    if (n > 0) this.beep(440 + (3 - n) * 80, 0.13, 0.2, 'square');
    else {
      this.beep(880, 0.1, 0.22, 'square');
      setTimeout(() => this.beep(1320, 0.28, 0.2, 'square'), 90);
    }
  }

  boost() {
    this.ensure();
    if (!this.ready || !this.sound) return;
    const t = this.ctx.currentTime;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noise;
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'bandpass'; filter.frequency.setValueAtTime(300, t); filter.frequency.exponentialRampToValueAtTime(3200, t + 0.28); filter.Q.value = 1.6;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(0.22, t + 0.03);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.42);
    src.connect(filter); filter.connect(g); g.connect(this.master);
    src.start(t); src.stop(t + 0.45);
  }

  pickup() {
    this.beep(980, 0.07, 0.13, 'triangle');
    setTimeout(() => this.beep(1480, 0.12, 0.12, 'triangle'), 60);
  }

  weatherChange(id) {
    this.ensure();
    if (!this.ready || !this.sound) return;
    if (id === 'storm' || id === 'rain') {
      const t = this.ctx.currentTime;
      const src = this.ctx.createBufferSource();
      src.buffer = this.noise;
      const f = this.ctx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = 420;
      const g = this.ctx.createGain();
      g.gain.setValueAtTime(0.0001, t);
      g.gain.exponentialRampToValueAtTime(0.12, t + 0.08);
      g.gain.exponentialRampToValueAtTime(0.0001, t + 1.6);
      src.connect(f); f.connect(g); g.connect(this.master);
      src.start(t); src.stop(t + 1.7);
    } else {
      this.beep(520, 0.16, 0.07, 'sine');
    }
  }

  finish(win) {
    this.ensure();
    if (!this.ready || !this.sound) return;
    const notes = win ? [523, 659, 784, 1047, 1319] : [392, 523, 659, 784];
    notes.forEach((f, i) => setTimeout(() => this.beep(f, 0.26, 0.16, 'triangle'), i * 110));
  }

  ui() {
    this.ensure();
    this.beep(720, 0.045, 0.05, 'sine');
  }

  crash() {
    this.ensure();
    if (!this.ready || !this.sound) return;
    const t = this.ctx.currentTime;
    const src = this.ctx.createBufferSource(); src.buffer = this.noise;
    const f = this.ctx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = 600;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.14, t); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.22);
    src.connect(f); f.connect(g); g.connect(this.master);
    src.start(t); src.stop(t + 0.24);
  }
}

/* ═══════════════════════════════════════════════════════════════
   RC RUSH — race simulation
   ═══════════════════════════════════════════════════════════════ */
import { generateTrack, curveAt, formatTime } from './track.js';
import { WeatherSystem } from './weather.js';

const clamp = (v, a, b) => Math.max(a, Math.min(b, v));

const AI_NAMES = [
  { name: 'KIRA', color: '#9d7bff', car: 'voltage', skill: 0.9 },
  { name: 'DEX', color: '#ffb03a', car: 'sidewinder', skill: 0.94 },
  { name: 'NOVA', color: '#35e6ff', car: 'glacier', skill: 0.98 }
];

export class Race {
  constructor({ location, car, seed, input, audio, onEvent }) {
    this.location = location;
    this.car = car;
    this.seed = seed;
    this.input = input;
    this.audio = audio;
    this.onEvent = onEvent || (() => {});

    this.track = generateTrack(location, seed);
    this.weather = new WeatherSystem(location, meta => {
      this.onEvent('weather', meta);
    });

    const s = car.stats;
    this.maxSpeed = 10400 + s.speed * 280;
    this.accel = 3450 + s.accel * 235;
    this.boostFactor = 1.155 + s.boost * 0.0135;
    this.gripBase = 0.82 + s.grip * 0.025;

    this.state = 'countdown';
    this.countdown = 3.25;
    this.lastCount = 4;
    this.time = 0;
    this.distance = 0;
    this.trackPos = 0;
    this.speed = 0;
    this.playerX = 0;
    this.boost = 100;
    this.boosting = false;
    this.drifting = false;
    this.offroad = false;
    this.grip = 1;
    this.rank = 4;
    this.lap = 1;
    this.laps = this.track.laps;
    this.lapStartTime = 0;
    this.lapTimes = [];
    this.topSpeed = 0;
    this.shake = 0;
    this.bumpCooldown = 0;
    this.driftTime = 0;
    this.pickups = 0;
    this.wrongWay = false;
    this.finishTime = 0;
    this.finalRank = 4;
    this.boostFlash = 0;

    this.ai = AI_NAMES.map((meta, i) => ({
      ...meta,
      distance: 900 + i * 900,
      speed: 0,
      x: (i - 1) * 0.18,
      phase: Math.random() * Math.PI * 2,
      lap: 1,
      finished: false,
      finishTime: 0
    }));

    this.weather.reset();
  }

  get speedRatio() { return this.speed / this.maxSpeed; }
  get kmh() { return Math.round(this.speed / 52); }
  get currentLapTime() { return Math.max(0, this.time - this.lapStartTime); }
  get lapProgress() { return clamp(this.trackPos / this.track.length, 0, 1); }
  get progressTotal() { return clamp(this.distance / (this.track.length * this.laps), 0, 1); }

  start() {
    this.state = 'countdown';
    this.countdown = 3.25;
    this.lastCount = 4;
    if (this.audio) this.audio.startRace();
  }

  update(dt) {
    dt = Math.min(dt, 0.05);

    if (this.state === 'countdown') {
      this.countdown -= dt;
      const n = Math.ceil(this.countdown);
      if (n !== this.lastCount && n >= 1 && n <= 3) {
        this.lastCount = n;
        if (this.audio) this.audio.countdown(n);
        this.onEvent('count', n);
      }
      if (this.countdown <= 0) {
        this.state = 'racing';
        this.countdown = 0;
        this.time = 0;
        this.lapStartTime = 0;
        if (this.audio) this.audio.countdown(0);
        this.onEvent('go');
      }
      this.weather.update(dt * 0.4);
      this._updateShake(dt);
      return;
    }

    if (this.state !== 'racing') {
      this._updateShake(dt);
      return;
    }

    this.time += dt;
    this.weather.update(dt);
    const wp = this.weather.params();
    this.grip = this.location.grip * wp.grip * this.gripBase;

    const steer = this.input.update(dt);
    const curve = curveAt(this.track, this.trackPos);
    const ratio = this.speedRatio;
    this.offroad = Math.abs(this.playerX) > 1.035;
    this.bumpCooldown = Math.max(0, this.bumpCooldown - dt);
    this.boostFlash = Math.max(0, this.boostFlash - dt);

    // ── steering & centrifugal drift ─────────────────────────
    const steerRate = (0.58 + 0.9 * Math.min(1, ratio)) * clamp(this.grip, 0.6, 1.25);
    this.playerX += steer * steerRate * dt * 1.28;
    this.playerX -= curve * ratio * ratio * 0.78 * dt / clamp(this.grip, 0.62, 1.2);
    this.playerX = clamp(this.playerX, -1.7, 1.7);
    if (Math.abs(this.playerX) > 1.56) {
      this.playerX += Math.sign(this.playerX) * -1.8 * dt;
    }

    // ── boost ────────────────────────────────────────────────
    const wantBoost = this.input.boost && this.boost > 0.5 && this.speed > 1600;
    this.boosting = wantBoost;
    if (wantBoost) {
      this.boost = Math.max(0, this.boost - 27 * dt);
      if (this.boostFlash <= 0) {
        this.boostFlash = 0.6;
        if (this.audio) this.audio.boost();
        this.onEvent('boost');
      }
    } else {
      const regen = this.drifting ? 9 : 4.2;
      this.boost = Math.min(100, this.boost + regen * dt);
    }

    // ── drift state ──────────────────────────────────────────
    const wasDrifting = this.drifting;
    this.drifting = Math.abs(steer) > 0.52 && ratio > 0.42 && !this.offroad;
    if (this.drifting && !wasDrifting) this.onEvent('drift-start');
    if (this.drifting) {
      this.driftTime += dt;
      if (!this.boosting) this.boost = Math.min(100, this.boost + 10.5 * dt);
    } else {
      this.driftTime = Math.max(0, this.driftTime - dt * 2);
    }

    // ── longitudinal physics ─────────────────────────────────
    let cap = this.maxSpeed * (this.boosting ? this.boostFactor : 1);
    if (this.offroad) cap *= 0.5;
    if (this.input.brake) {
      this.speed = Math.max(0, this.speed - 15500 * dt);
    } else if (this.speed < cap) {
      const headroom = 1 - Math.min(1, this.speed / this.maxSpeed);
      this.speed += this.accel * (0.7 + headroom * 0.42) * dt;
      if (this.boosting) this.speed += this.accel * 0.55 * dt;
    } else {
      this.speed -= ((this.speed - cap) * 2.2 + 120) * dt;
    }
    if (this.offroad) this.speed = Math.max(0, this.speed - 5200 * dt);
    this.speed = clamp(this.speed, 0, this.maxSpeed * this.boostFactor * 1.04);
    this.topSpeed = Math.max(this.topSpeed, this.speed);

    // ── advance ──────────────────────────────────────────────
    const prevPos = this.trackPos;
    const prevDist = this.distance;
    this.distance += this.speed * dt;
    this.trackPos = this.distance % this.track.length;

    // lap crossing
    const newLap = Math.min(this.laps, Math.floor(this.distance / this.track.length) + 1);
    if (newLap > this.lap) {
      const lapTime = this.time - this.lapStartTime;
      this.lapTimes.push(lapTime);
      this.lapStartTime = this.time;
      this.lap = newLap;
      this.onEvent('lap', { lap: newLap, lapTime });
      if (this.audio) this.audio.beep(newLap === this.laps ? 760 : 620, 0.14, 0.12, 'triangle');
    }

    // finish
    if (this.distance >= this.track.length * this.laps) {
      this._finish();
      return;
    }

    this._updateAI(dt);
    this._checkPads(prevPos, this.trackPos);
    this._checkCollisions();
    this._updateStandings();
    this._updateShake(dt);

    if (this.audio) {
      this.audio.update(dt, ratio, this.boosting, this.offroad, this.drifting ? 1 : 0);
    }
  }

  _updateAI(dt) {
    const trackLen = this.track.length;
    for (const ai of this.ai) {
      if (ai.finished) continue;
      const curve = Math.abs(curveAt(this.track, ai.distance));
      const wp = this.weather.params();
      const diff = this.distance - ai.distance;
      const rubber = clamp(diff / 30000, -0.075, 0.065);
      const base = this.maxSpeed * (0.82 + ai.skill * 0.13);
      const target = base * (1 - curve * 0.075) * clamp(wp.grip, 0.78, 1.05) * (1 + rubber);
      ai.speed += (target - ai.speed) * Math.min(1, dt * 1.6);
      if (ai.speed < target) ai.speed += 3800 * dt;
      ai.distance += ai.speed * dt;

      const targetX = clamp(-curve * 0.55 + Math.sin(ai.distance * 0.00045 + ai.phase) * 0.12, -0.82, 0.82);
      ai.x += (targetX - ai.x) * Math.min(1, dt * 1.4);
      ai.lap = Math.floor(ai.distance / trackLen) + 1;
      if (ai.distance >= trackLen * this.laps) {
        ai.distance = trackLen * this.laps;
        ai.finished = true;
        ai.finishTime = this.time;
      }
    }
  }

  _checkPads(prevPos, currPos) {
    const segLen = this.track.segmentLength;
    const total = this.track.total;
    const prevIdx = Math.floor(prevPos / segLen);
    const currIdx = Math.floor(currPos / segLen);
    const wrapped = currIdx < prevIdx;
    for (const pad of this.track.boostPads) {
      pad.cooldown = Math.max(0, pad.cooldown - 0.016);
      if (pad.cooldown > 0) continue;
      let crossed = false;
      if (!wrapped) crossed = pad.index >= prevIdx && pad.index <= currIdx;
      else crossed = pad.index >= prevIdx || pad.index <= currIdx;
      if (!crossed) continue;
      if (Math.abs(this.playerX - pad.x) > 0.34) continue;
      pad.cooldown = 5;
      this.boost = Math.min(100, this.boost + 26);
      this.pickups++;
      this.onEvent('pickup', { x: pad.x });
      if (this.audio) this.audio.pickup();
    }
  }

  _checkCollisions() {
    if (this.bumpCooldown > 0) return;
    for (const ai of this.ai) {
      let dz = ai.distance - this.distance;
      if (dz > this.track.length / 2) dz -= this.track.length;
      if (dz < -this.track.length / 2) dz += this.track.length;
      if (Math.abs(dz) < 360 && Math.abs(ai.x - this.playerX) < 0.32) {
        this.speed *= 0.94;
        this.playerX += Math.sign(this.playerX - ai.x || 1) * 0.07;
        ai.x -= Math.sign(this.playerX - ai.x || 1) * 0.07;
        this.bumpCooldown = 0.7;
        this.shake = Math.max(this.shake, 0.55);
        this.onEvent('bump');
        if (this.audio) this.audio.crash();
        if (navigator.vibrate) navigator.vibrate(28);
        return;
      }
    }
  }

  _updateStandings() {
    const list = this.getStandings();
    this.rank = list.findIndex(r => r.isPlayer) + 1;
  }

  getStandings() {
    const list = this.ai.map(a => ({
      name: a.name, color: a.color, distance: a.distance, isPlayer: false,
      finished: a.finished, finishTime: a.finishTime, car: a.car
    }));
    list.push({
      name: 'YOU', color: this.car.color, distance: this.distance, isPlayer: true,
      finished: this.state === 'finished', finishTime: this.finishTime, car: this.car.id
    });
    list.sort((a, b) => b.distance - a.distance);
    return list;
  }

  _finish() {
    this.state = 'finished';
    this.finishTime = this.time;
    if (this.lapTimes.length < this.laps) {
      this.lapTimes.push(this.time - this.lapStartTime);
    }
    const standings = this.getStandings();
    this.finalRank = standings.findIndex(r => r.isPlayer) + 1;
    this.rank = this.finalRank;
    this.speed *= 0.7;
    if (this.audio) {
      this.audio.stopRace();
      this.audio.finish(this.finalRank === 1);
    }
    this.onEvent('finish', {
      rank: this.finalRank,
      time: this.finishTime,
      lapTimes: [...this.lapTimes],
      topSpeed: this.kmh,
      standings,
      weather: this.weather.current
    });
  }

  _updateShake(dt) {
    this.shake = Math.max(0, this.shake - dt * 1.8);
    if (this.offroad && this.speed > 3000) this.shake = Math.max(this.shake, 0.25);
    if (this.boosting) this.shake = Math.max(this.shake, 0.18);
  }

  bestLap() {
    return this.lapTimes.length ? Math.min(...this.lapTimes) : 0;
  }

  statusLine() {
    if (this.state === 'countdown') return 'GET READY';
    return formatTime(this.time);
  }
}

/* ═══════════════════════════════════════════════════════════════
   RC RUSH — colour helpers
   ═══════════════════════════════════════════════════════════════ */

export function hexToRgb(hex) {
  let h = hex.replace('#', '').trim();
  if (h.length === 3) h = h.split('').map(c => c + c).join('');
  const n = parseInt(h, 16);
  if (!Number.isFinite(n)) return { r: 0, g: 0, b: 0 };
  return { r: (n >> 16) & 255, g: (n >> 8) & 255, b: n & 255 };
}

export function rgbToHex(r, g, b) {
  const c = v => Math.max(0, Math.min(255, Math.round(v))).toString(16).padStart(2, '0');
  return `#${c(r)}${c(g)}${c(b)}`;
}

export function mix(a, b, t) {
  const A = hexToRgb(a), B = hexToRgb(b);
  return rgbToHex(A.r + (B.r - A.r) * t, A.g + (B.g - A.g) * t, A.b + (B.b - A.b) * t);
}

export function rgba(hex, alpha) {
  const { r, g, b } = hexToRgb(hex);
  return `rgba(${r},${g},${b},${alpha})`;
}

export function shade(hex, amount) {
  return amount >= 0 ? mix(hex, '#ffffff', amount) : mix(hex, '#000000', -amount);
}

export function hashString(str) {
  let h = 2166136261;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

export function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }

