86:       x: rnd(), y: rnd() * 0.44, r: 0.5 + rnd() * 1.5, ph: rnd() * Math.PI * 2
87:     }));
88:     this.clouds = Array.from({ length: 9 }, () => ({
89:       x: rnd(), y: 0.09 + rnd() * 0.3, s: 0.5 + rnd() * 1.2, sp: 0.003 + rnd() * 0.006, a: 0.12 + rnd() * 0.2
90:     }));
91:     this.speedLines = Array.from({ length: 34 }, () => ({
92:       a: rnd() * Math.PI * 2, r: 0.18 + rnd() * 0.45, len: 0.05 + rnd() * 0.14, ph: rnd() * Math.PI * 2
93:     }));
94:   }
95: 
96:   mixCached(color, target, t) {
97:     const q = Math.round(clamp(t, 0, 1) * 24) / 24;
98:     const key = color + target + q;
99:     let v = this.colorCache.get(key);
100:     if (v === undefined) {
101:       v = mix(color, target, q);
102:       if (this.colorCache.size > 4000) this.colorCache.clear();
103:       this.colorCache.set(key, v);
104:     }
105:     return v;
106:   }
107: 
108:   render(race, dt, now) {
109:     const rect = this.canvas.getBoundingClientRect();
110:     if (Math.abs(rect.width - this.w) > 0.5 || Math.abs(rect.height - this.h) > 0.5) this.resize();
111:     if (this.track !== race.track) this.setTrack(race.track, race.location);
112: 
113:     const ctx = this.ctx;
114:     const w = this.w, h = this.h;
115:     const loc = this.location;
116:     const wp = race.weather.params();
117:     const horizon = h * 0.5;
118:     const ratio = race.speedRatio || 0;
119:     const fogColor = mix(loc.fog, wp.tint, wp.tintAlpha * 0.62);
120:     this.wet = (wp.id === 'rain' || wp.id === 'storm') ? 1 : 0;
121: 
122:     const steer = race.input ? race.input.steer : 0;
123:     const carW = clamp(Math.min(w * 0.34, h * 0.30), 118, 232);
124:     const carBase = h - clamp(h * 0.16, 96, 152);
125:     const carX = w * 0.5 + steer * w * 0.016;
126:     const carRot = steer * 0.075 + (race.curveVisual || 0) * 0.02;
127: 
128:     this.bgScroll += race.speed * dt * 0.012 + steer * dt * 22;
129:     this._updateSmoke(race, dt, carX, carBase, carW, now);
130:     this._updateParticles(race, dt, wp, ratio, now);
131: 
132:     const shake = race.shake || 0;
133:     const shx = Math.sin(now * 61) * shake * 9 + Math.sin(now * 23) * shake * 4;
134:     const shy = Math.cos(now * 53) * shake * 7 + Math.cos(now * 31) * shake * 3;
135: 
136:     ctx.save();
137:     ctx.translate(shx, shy);
138: 
139:     this._drawSky(race, wp, now, horizon, fogColor);
140:     this._drawBackdrop(race, horizon);
141:     this._drawGround(horizon, fogColor);
142: 
143:     const depth = 0.9 - (race.boosting ? 0.055 : 0) - ratio * 0.006;
144:     const playerZ = CAMERA_HEIGHT * depth;
145:     const pos = race.trackPos;
146:     const playerSeg = race.track.segments[Math.floor(((pos + playerZ) % race.track.length) / race.track.segmentLength) % race.track.total];
147:     const playerPct = ((pos + playerZ) % race.track.segmentLength) / race.track.segmentLength;
148:     const playerY = interpolate(playerSeg.p1.world.y, playerSeg.p2.world.y, playerPct);
149: 
150:     const { projected, sprites } = this._drawRoad(race, wp, now, depth, playerY, fogColor, horizon);
151: 
152:     // opponents
153:     for (const ai of race.ai) {
154:       const idx = Math.floor((ai.distance % race.track.length) / race.track.segmentLength) % race.track.total;
155:       const proj = projected.get(idx);
156:       if (!proj) continue;
157:       const unit = proj.p1.scale * h * 0.5;
158:       const cw = unit * 940;
159:       if (cw < 3 || cw > 600) continue;
160:       sprites.push({
161:         n: proj.n,
162:         kind: 'car',
163:         ai,
164:         fog: proj.fog,
165:         x: proj.p1.x + ai.x * proj.p1.w,
166:         y: proj.p1.y,
167:         w: cw
168:       });
169:     }
170: 
171:     sprites.sort((a, b) => b.n - a.n);
172:     for (const s of sprites) {
173:       if (s.kind === 'prop') {
174:         drawProp(ctx, s.prop, s.x, s.y, s.unit, loc, s.fog, fogColor, now, s.roadPx);
175:       } else {
176:         drawOpponent(ctx, s.x, s.y, s.w, s.ai, s.fog, now);
177:       }
178:     }
179: 
180:     this._drawSmoke();
181:     this._drawPlayer(race, carX, carBase, carW, carRot, now);
182:     this._drawFog(wp, horizon, fogColor);
183:     this._drawParticles(wp, now);
184:     this._drawLightning(race, wp);
185:     this._drawSpeedLines(ratio, race.boosting, now);
186: 
187:     ctx.restore();
188: 
189:     this._drawVignette(race, ratio);
190:   }
191: 
192:   _drawSky(race, wp, now, horizon, fogColor) {
193:     const ctx = this.ctx, w = this.w, h = this.h, loc = this.location;
194:     let top = mix(loc.sky.top, '#05070c', wp.skyDim * 0.55);
195:     let mid = mix(loc.sky.mid, '#05070c', wp.skyDim * 0.42);
196:     let bot = mix(loc.sky.bottom, '#0a0d16', wp.skyDim * 0.32);
197:     top = mix(top, wp.tint, wp.tintAlpha * 0.55);
198:     mid = mix(mid, wp.tint, wp.tintAlpha * 0.45);
199:     bot = mix(bot, wp.tint, wp.tintAlpha * 0.38);
200: 
201:     const sky = ctx.createLinearGradient(0, 0, 0, horizon + 2);
202:     sky.addColorStop(0, top);
203:     sky.addColorStop(0.52, mid);
204:     sky.addColorStop(1, bot);
205:     ctx.fillStyle = sky;
206:     ctx.fillRect(0, 0, w, horizon + 3);
207: 
208:     // stars
209:     if (loc.stars) {
210:       const a = (1 - wp.skyDim * 0.75) * (0.45 + 0.35 * (1 - wp.tintAlpha * 3));
211:       for (const s of this.stars) {
212:         const tw = 0.55 + Math.sin(now * 1.4 + s.ph) * 0.45;
213:         ctx.globalAlpha = clamp(a * tw, 0, 1);
214:         ctx.fillStyle = '#eaf6ff';
215:         ctx.fillRect(s.x * w, s.y * horizon, s.r, s.r);
216:       }
217:       ctx.globalAlpha = 1;
218:     }
219: 
220:     // sun / moon
221:     const sx = loc.sun.x * w;
222:     const sy = horizon * (0.16 + loc.sun.y * 0.9);
223:     const sr = loc.sun.size * h;
224:     const glow = ctx.createRadialGradient(sx, sy, 0, sx, sy, sr * 5.5);
225:     glow.addColorStop(0, rgba(loc.sun.color, 0.5 * (1 - wp.skyDim * 0.6)));
226:     glow.addColorStop(0.25, rgba(loc.sun.color, 0.16 * (1 - wp.skyDim * 0.6)));
227:     glow.addColorStop(1, rgba(loc.sun.color, 0));
228:     ctx.fillStyle = glow;
229:     ctx.fillRect(sx - sr * 6, sy - sr * 6, sr * 12, sr * 12);
230:     ctx.globalAlpha = 1 - wp.skyDim * 0.65;
231:     ctx.fillStyle = loc.sun.color;
232:     ctx.beginPath();
233:     ctx.arc(sx, sy, sr, 0, Math.PI * 2);
234:     ctx.fill();
235:     if (loc.sun.type === 'moon') {
236:       ctx.fillStyle = 'rgba(80,100,130,.16)';
237:       ctx.beginPath(); ctx.arc(sx - sr * 0.3, sy - sr * 0.2, sr * 0.22, 0, Math.PI * 2); ctx.fill();
238:       ctx.beginPath(); ctx.arc(sx + sr * 0.32, sy + sr * 0.24, sr * 0.15, 0, Math.PI * 2); ctx.fill();
239:       ctx.beginPath(); ctx.arc(sx + sr * 0.1, sy - sr * 0.42, sr * 0.1, 0, Math.PI * 2); ctx.fill();
240:     }
241:     ctx.globalAlpha = 1;
242: 
243:     // clouds
244:     if (loc.backdrop !== 'space') {
245:       const cloudColor = mix(loc.fog, wp.tint, 0.3);
246:       const stormy = wp.id === 'storm' || wp.id === 'rain';
247:       for (const c of this.clouds) {
248:         const cx = ((c.x + now * c.sp) % 1.25 - 0.12) * w;
249:         const cy = c.y * horizon;
250:         const cs = c.s * h * 0.05;
251:         ctx.fillStyle = rgba(cloudColor, c.a * (stormy ? 1.4 : 0.75));
252:         ctx.beginPath();
253:         ctx.ellipse(cx, cy, cs * 2.1, cs * 0.55, 0, 0, Math.PI * 2);
254:         ctx.ellipse(cx + cs * 0.9, cy - cs * 0.25, cs * 1.2, cs * 0.5, 0, 0, Math.PI * 2);
255:         ctx.ellipse(cx - cs * 0.9, cy + cs * 0.05, cs * 1.3, cs * 0.42, 0, 0, Math.PI * 2);
256:         ctx.fill();
257:       }
258:     }
259: 
260:     // horizon glow
261:     const hg = ctx.createLinearGradient(0, horizon - h * 0.09, 0, horizon + h * 0.04);
262:     hg.addColorStop(0, rgba(loc.accent, 0));
263:     hg.addColorStop(0.55, rgba(loc.accent, 0.1));
264:     hg.addColorStop(1, rgba(fogColor, 0.28));
265:     ctx.fillStyle = hg;
266:     ctx.fillRect(0, horizon - h * 0.09, w, h * 0.13);
267:   }
268: 
269:   _drawBackdrop(race, horizon) {
270:     const ctx = this.ctx, w = this.w, h = this.h;
271:     for (let i = 0; i < this.layers.length; i++) {
272:       const img = this.layers[i];
273:       if (!img) continue;
274:       const layerH = h * (i === 0 ? 0.44 : 0.55);
275:       const lw = 2400 * (layerH / 620);
276:       const factor = i === 0 ? 0.28 : 0.58;
277:       const off = ((this.bgScroll * factor) % lw + lw) % lw;
278:       const y = horizon - layerH + h * 0.025;
279:       ctx.globalAlpha = i === 0 ? 0.9 : 1;
280:       for (let x = -off - lw; x < w + lw; x += lw) {
281:         ctx.drawImage(img, x, y, lw, layerH);
282:       }
283:       ctx.globalAlpha = 1;
284:     }
285:   }
286: 
287:   _drawGround(horizon, fogColor) {
288:     const ctx = this.ctx, w = this.w, h = this.h, loc = this.location;
289:     const g = ctx.createLinearGradient(0, horizon, 0, h);
290:     g.addColorStop(0, mix(loc.ground[0], fogColor, 0.55));
291:     g.addColorStop(0.25, mix(loc.ground[0], fogColor, 0.28));
292:     g.addColorStop(1, mix(loc.ground[0], '#05070c', 0.24));
293:     ctx.fillStyle = g;
294:     ctx.fillRect(0, horizon, w, h - horizon + 2);
295:   }
296: 
297:   _drawRoad(race, wp, now, depth, playerY, fogColor, horizon) {
298:     const ctx = this.ctx, w = this.w, h = this.h, loc = this.location;
299:     const track = race.track;
300:     const segs = track.segments;
301:     const N = track.total;
302:     const len = track.length;
303:     const segLen = track.segmentLength;
304:     const pos = race.trackPos;
305:     const baseIndex = Math.floor(pos / segLen) % N;
306:     const basePct = (pos % segLen) / segLen;
307:     const base = segs[baseIndex];
308:     const playerX = race.playerX;
309: 
310:     let x = 0;
311:     let dx = -(base.curve * basePct);
312:     let maxy = h;
313:     const projected = new Map();
314:     const sprites = [];
315:     const drawDist = Math.min(FOG_FAR, N - 1);
316:     const fogBase = wp.fog * 2.9;
317: 
318:     for (let n = 0; n < drawDist; n++) {
319:       const seg = segs[(baseIndex + n) % N];
320:       const looped = seg.index < baseIndex;
321:       const camZ = pos - (looped ? len : 0);
322:       project(seg.p1, playerX * track.roadWidth - x, playerY + CAMERA_HEIGHT, camZ, depth, w, h, track.roadWidth);
323:       project(seg.p2, playerX * track.roadWidth - x - dx, playerY + CAMERA_HEIGHT, camZ, depth, w, h, track.roadWidth);
324:       x += dx;
325:       dx += seg.curve;
326: 
327:       if (seg.p1.camera.z <= depth || seg.p2.screen.y >= seg.p1.screen.y || seg.p2.screen.y >= maxy) continue;
328: 
329:       const fog = 1 - Math.exp(-Math.pow(n / drawDist, 2.15) * fogBase);
330:       this._drawSegment(seg, fog, fogColor, now);
331:       const p1 = { x: seg.p1.screen.x, y: seg.p1.screen.y, w: seg.p1.screen.w, scale: seg.p1.screen.scale };
332:       const p2 = { x: seg.p2.screen.x, y: seg.p2.screen.y, w: seg.p2.screen.w };
333:       projected.set(seg.index, { p1, p2, n, fog });
334: 
335:       if (seg.props.length) {
336:         const unit = seg.p1.screen.scale * h * 0.5;
337:         for (const prop of seg.props) {
338:           sprites.push({
339:             n, kind: 'prop', prop, fog,
340:             x: seg.p1.screen.x + prop.offset * seg.p1.screen.w,
341:             y: seg.p1.screen.y,
342:             unit,
343:             roadPx: seg.p1.screen.w
344:           });
345:         }
346:       }
347: 
348:       maxy = seg.p2.screen.y;
349:     }
350:     return { projected, sprites };
351:   }
352: 
353:   _drawSegment(seg, fog, fogColor, now) {
354:     const ctx = this.ctx, w = this.w;
355:     const loc = this.location;
356:     const p1 = seg.p1.screen, p2 = seg.p2.screen;
357:     const y1 = p1.y, y2 = p2.y;
358:     if (y1 <= y2) return;
359:     const x1 = p1.x, x2 = p2.x;
360:     const w1 = p1.w, w2 = p2.w;
361:     const band = Math.floor(seg.index / 4) % 2;
362:     const roadBand = Math.floor(seg.index / 3) % 2;
363:     const rumbleBand = Math.floor(seg.index / 3) % 2;
364:     const ground = this.mixCached(loc.ground[band], fogColor, fog);
365:     const road = this.mixCached(loc.road[roadBand], fogColor, fog);
366:     const rumble = this.mixCached(loc.rumble[rumbleBand], fogColor, fog);
367:     const lane = this.mixCached(loc.lane, fogColor, fog);
368: 
369:     ctx.fillStyle = ground;
370:     ctx.fillRect(0, y2, w, y1 - y2 + 1);
371: 
372:     // rumble strips
373:     quad(ctx, x1 - w1, y1, x1 - w1 * 0.82, y1, x2 - w2 * 0.82, y2, x2 - w2, y2, rumble);
374:     quad(ctx, x1 + w1 * 0.82, y1, x1 + w1, y1, x2 + w2, y2, x2 + w2 * 0.82, y2, rumble);
375: 
376:     // road
377:     quad(ctx, x1 - w1 * 0.82, y1, x1 + w1 * 0.82, y1, x2 + w2 * 0.82, y2, x2 - w2 * 0.82, y2, road);
378: 
379:     // wet sheen
380:     if (this.wet > 0.1 || seg.wet) {
381:       const alpha = this.wet > 0.1 ? 0.07 + Math.sin(seg.index * 1.7) * 0.025 : 0.11;
382:       quad(ctx, x1 - w1 * 0.82, y1, x1 + w1 * 0.82, y1, x2 + w2 * 0.82, y2, x2 - w2 * 0.82, y2, rgba(loc.sky.bottom, alpha));
383:       if (seg.wet) {
384:         ctx.fillStyle = rgba(loc.sky.bottom, 0.16);
385:         ctx.beginPath();
386:         ctx.ellipse(x1 + (seg.wetSeed - 0.5) * w1 * 0.7, (y1 + y2) / 2, w1 * (0.14 + seg.wetSeed * 0.12), Math.max(1, (y1 - y2) * 0.24), 0, 0, Math.PI * 2);
387:         ctx.fill();
388:       }
389:     }
390: 
391:     // edge lines
392:     const edge = rgba(lane, 0.55);
393:     quad(ctx, x1 - w1 * 0.82, y1, x1 - w1 * 0.79, y1, x2 - w2 * 0.79, y2, x2 - w2 * 0.82, y2, edge);
394:     quad(ctx, x1 + w1 * 0.79, y1, x1 + w1 * 0.82, y1, x2 + w2 * 0.82, y2, x2 + w2 * 0.79, y2, edge);
395: 
396:     // centre dash
397:     if (Math.floor(seg.index / 4) % 2 === 0 && !['sand', 'dirt', 'mud'].includes(loc.surface)) {
398:       quad(ctx, x1 - w1 * 0.018, y1, x1 + w1 * 0.018, y1, x2 + w2 * 0.018, y2, x2 - w2 * 0.018, y2, rgba(lane, 0.6));
399:     }
400: 
401:     // start / finish checker
402:     if (seg.finish) {
403:       const cols = 10, rows = 2;
404:       for (let r = 0; r < rows; r++) {
405:         const t0 = r / rows, t1 = (r + 1) / rows;
406:         const ya = y1 + (y2 - y1) * t0, yb = y1 + (y2 - y1) * t1;
407:         const wa = w1 + (w2 - w1) * t0, wb = w1 + (w2 - w1) * t1;
408:         const xa = x1 + (x2 - x1) * t0, xb = x1 + (x2 - x1) * t1;
409:         for (let c = 0; c < cols; c++) {
410:           const c0 = c / cols, c1 = (c + 1) / cols;
411:           const fill = (c + r) % 2 ? 'rgba(248,250,255,.92)' : 'rgba(12,16,24,.92)';
412:           quad(ctx,
413:             xa - wa * 0.82 + wa * 1.64 * c0, ya,
414:             xa - wa * 0.82 + wa * 1.64 * c1, ya,
415:             xb - wb * 0.82 + wb * 1.64 * c1, yb,
416:             xb - wb * 0.82 + wb * 1.64 * c0, yb,
417:             fill);
418:         }
419:       }
420:     }
421: 
422:     // boost pad
423:     const pad = this.padMap && this.padMap.get(seg.index);
424:     if (pad) this._drawPad(pad, p1, now);
425:   }
426: 
427:   _drawPad(pad, p1, now) {
428:     const ctx = this.ctx;
429:     const cx = p1.x + pad.x * p1.w;
430:     const cy = p1.y;
431:     const s = p1.w * 0.16;
432:     const pulse = 0.7 + Math.sin(now * 5 + pad.phase) * 0.3;
433:     ctx.save();
434:     ctx.translate(cx, cy);
435:     ctx.globalAlpha = pad.cooldown > 0 ? 0.15 : 0.9 * pulse;
436:     ctx.strokeStyle = this.location.accent2;
437:     ctx.lineWidth = Math.max(1.2, s * 0.22);
438:     ctx.lineCap = 'round';
439:     for (let i = 0; i < 3; i++) {
440:       const yy = -i * s * 0.55;
441:       ctx.beginPath();
442:       ctx.moveTo(-s * 0.55, yy + s * 0.4);
443:       ctx.lineTo(0, yy);
444:       ctx.lineTo(s * 0.55, yy + s * 0.4);
445:       ctx.stroke();
446:     }
447:     ctx.globalAlpha = 0.28 * pulse;
448:     ctx.fillStyle = this.location.accent2;
449:     ctx.beginPath();
450:     ctx.ellipse(0, -s * 0.3, s * 1.2, s * 0.6, 0, 0, Math.PI * 2);
451:     ctx.fill();
452:     ctx.restore();
453:   }
454: 
455:   _drawPlayer(race, x, y, width, rot, now) {
456:     const ctx = this.ctx;
457:     const bounce = Math.sin(now * 19) * race.speedRatio * 1.8 + (race.offroad ? Math.sin(now * 51) * 2.4 : 0);
458:     drawRCCar(ctx, x, y + bounce, width, race.car, {
459:       rot,
460:       boost: race.boosting ? 1 : 0,
461:       brake: race.input && race.input.brake,
462:       now,
463:       steer: race.input ? race.input.steer : 0,
464:       drift: race.drifting ? 1 : 0
465:     });
466:   }
467: 
468:   _updateSmoke(race, dt, carX, carBase, carW, now) {
469:     if (race.state === 'racing' && (race.drifting || race.offroad || race.boosting)) {
470:       this.smokeTimer -= dt;
471:       if (this.smokeTimer <= 0) {
472:         this.smokeTimer = 0.028;
473:         const color = race.boosting ? '#ffb03a' : race.offroad ? this.location.ground[1] : '#dbe9f5';
474:         const count = race.boosting ? 2 : 1;
475:         for (let i = 0; i < count; i++) {
476:           this.smoke.push({
477:             x: carX + (Math.random() * 2 - 1) * carW * 0.42,
478:             y: carBase - Math.random() * 10,
479:             vx: (Math.random() * 2 - 1) * 60 - (race.input ? race.input.steer : 0) * 90,
480:             vy: -18 - Math.random() * 42,
481:             life: 0.55 + Math.random() * 0.35,
482:             max: 0.9,
483:             size: carW * (0.05 + Math.random() * 0.07),
484:             color
485:           });
486:         }
487:       }
488:     }
489:     for (let i = this.smoke.length - 1; i >= 0; i--) {
490:       const p = this.smoke[i];
491:       p.life -= dt;
492:       p.x += p.vx * dt;
493:       p.y += p.vy * dt;
494:       p.vy += 30 * dt;
495:       p.size += dt * 50;
496:       if (p.life <= 0) this.smoke.splice(i, 1);
497:     }
498:   }
499: 
500:   _drawSmoke() {
501:     const ctx = this.ctx;
502:     for (const p of this.smoke) {
503:       ctx.globalAlpha = clamp(p.life / p.max, 0, 1) * 0.32;
504:       ctx.fillStyle = p.color;
505:       ctx.beginPath();
506:       ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
507:       ctx.fill();
508:     }
509:     ctx.globalAlpha = 1;
510:   }
511: 
512:   _updateParticles(race, dt, wp, ratio, now) {
513:     const w = this.w, h = this.h;
514:     const kind = wp.kind;
515:     const target = Math.min(340, Math.round(wp.particles * (w < 720 ? 0.7 : 1)));
516:     if (kind !== this.particleKind) {
517:       this.particleKind = kind;
518:       this.particles = [];
519:     }
520:     if (!kind || target <= 0) { this.particles.length = 0; return; }
521:     while (this.particles.length < target) {
522:       this.particles.push(this._newParticle(kind, w, h, true));
523:     }
524:     if (this.particles.length > target) this.particles.length = target;
525: 
526:     for (const p of this.particles) {
527:       if (kind === 'rain') {
